* { margin: 0; padding: 0; box-sizing: border-box; }
body {
  font-family: 'Segoe UI', system-ui, sans-serif;
  background: #0f172a;
  color: #e2e8f0;
  padding: 16px;
}
.topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 16px;
}
.brand {
  display: flex;
  align-items: center;
  gap: 8px;
  font-weight: 800;
  font-size: 18px;
}
.dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: #38bdf8;
  box-shadow: 0 0 12px #38bdf8;
}
.btn {
  background: #38bdf8;
  color: #0f172a;
  border: 0;
  padding: 8px 14px;
  border-radius: 8px;
  font-weight: 700;
  cursor: pointer;
}
.stats {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px;
}
.card {
  background: #1e293b;
  border-radius: 12px;
  padding: 16px;
  border: 1px solid #334155;
}
.card.up b { color: #4ade80; }
.label {
  display: block;
  font-size: 12px;
  color: #94a3b8;
  margin-bottom: 6px;
}
b { font-size: 26px; }
.panel {
  display: grid;
  grid-template-columns: 2fr 1fr;
  gap: 12px;
  margin-top: 12px;
}
h3 {
  font-size: 14px;
  margin-bottom: 10px;
  color: #94a3b8;
}
.bars {
  display: flex;
  align-items: flex-end;
  gap: 6px;
  height: 120px;
}
.bars div {
  flex: 1;
  border-radius: 4px 4px 0 0;
  background: linear-gradient(#38bdf8, #1d4ed8);
  transition: height .4s;
}
ul { list-style: none; }
li {
  font-size: 12px;
  color: #cbd5e1;
  padding: 6px 0;
  border-bottom: 1px solid #334155;
}
li b { font-size: 12px; }

const visitors = document.getElementById('visitors')
const orders = document.getElementById('orders')
const latency = document.getElementById('latency')
const bars = document.getElementById('bars')
const feed = document.getElementById('feed')
const addBtn = document.getElementById('addBtn')

let current = [320, 410, 380, 540, 610, 720, 580]
const actions = [
  'membuka halaman produk',
  'menambahkan item ke keranjang',
  'menyelesaikan transaksi',
  'melihat laporan analitik',
  'masuk melalui aplikasi mobile'
]

function renderBars() {
  const max = Math.max(...current, 1)
  bars.innerHTML = ''
  current.forEach((v) => {
    const el = document.createElement('div')
    el.style.height = `${(v / max) * 100}%`
    bars.appendChild(el)
  })
}

function addActivity() {
  const action = actions[Math.floor(Math.random() * actions.length)]
  const li = document.createElement('li')
  li.innerHTML = `<b>${(Math.random() * 1.2 + 0.2).toFixed(2)}s lalu</b> — pengunjung ${action}`
  feed.prepend(li)
  while (feed.children.length > 6) feed.lastChild.remove()
}

function simulate() {
  visitors.textContent = (Number(visitors.textContent.replace(/\D/g, '')) + Math.floor(Math.random() * 40 + 10)).toLocaleString('id-ID')
  orders.textContent = String(Number(orders.textContent) + Math.floor(Math.random() * 6 + 1))
  latency.textContent = `${Math.floor(Math.random() * 120 + 90)}ms`
  current = current.map((v) => Math.max(60, v + Math.floor(Math.random() * 90 - 30)))
  renderBars()
  addActivity()
}

addBtn.addEventListener('click', simulate)
renderBars()
for (let i = 0; i < 5; i++) addActivity()
